You are Antigravity, an agentic AI coding assistant. Your task is to autonomously integrate this React component into the current workspace codebase using your available tools.

## Autonomous Workflow:
1. **Inspect Workspace Context**:
   - Determine the component directory structure (e.g. `components/ui/`, `src/components/ui/`, or `components/`).
   - Detect the active package manager from lockfiles (`pnpm`, `npm`, `yarn`, or `bun`).
   - Check the styling configuration (Tailwind v3 in `tailwind.config.{js,ts}` or Tailwind v4 in `globals.css` / `index.css`).

2. **Write Component Files**:
   - Use `write_to_file` to create the component at `components/auto-index/emerald-hover-border-gradient/hover-border-gradient.tsx` (or the project's corresponding path) with the complete implementation below.
   - If any registry dependencies are provided, write each helper file to its proper path.
   - Create or update an example showcase page/view using the demo code below so the component can be tested immediately.

3. **Install Dependencies**:
   - Run the installation command via `run_command`:
     ```bash
     npm install 0  # (adapt to detected pnpm / yarn / bun)
     ```

4. **Configure Styling & Animations**:
   - If custom keyframes, animations, or Tailwind extensions are specified below, use `replace_file_content` to merge them into the project's Tailwind config or CSS file.

5. **Verification**:
   - Verify zero TypeScript or lint errors.
   - Ensure all icon imports (e.g. from `lucide-react`) and helper utilities resolve cleanly.

---

### Component Code (`hover-border-gradient.tsx`):
```tsx
'use client'
import React, { useState, useEffect } from 'react'
import { motion } from 'motion/react'
import { cn } from '@/lib/utils'

type Direction = 'TOP' | 'LEFT' | 'BOTTOM' | 'RIGHT'

const movingMap: Record<Direction, string> = {
  TOP: 'radial-gradient(20.7% 50% at 50% 0%, hsl(0, 0%, 100%) 0%, rgba(255, 255, 255, 0) 100%)',
  LEFT: 'radial-gradient(16.6% 43.1% at 0% 50%, hsl(0, 0%, 100%) 0%, rgba(255, 255, 255, 0) 100%)',
  BOTTOM:
    'radial-gradient(20.7% 50% at 50% 100%, hsl(0, 0%, 100%) 0%, rgba(255, 255, 255, 0) 100%)',
  RIGHT:
    'radial-gradient(16.2% 41.199999999999996% at 100% 50%, hsl(0, 0%, 100%) 0%, rgba(255, 255, 255, 0) 100%)',
}

const highlight =
  'radial-gradient(75% 181.15942028985506% at 50% 50%, #3275F8 0%, rgba(255, 255, 255, 0) 100%)'

function HoverBorderGradient({
  children,
  containerClassName,
  className,
  as: Element = 'button',
  duration = 1,
  clockwise = true,
  ...props
}: React.PropsWithChildren<
  {
    as?: React.ElementType
    containerClassName?: string
    className?: string
    duration?: number
    clockwise?: boolean
  } & React.HTMLAttributes<HTMLElement>
>) {
  const [hovered, setHovered] = useState<boolean>(false)
  const [direction, setDirection] = useState<Direction>('BOTTOM')

  const rotateDirection = (currentDirection: Direction): Direction => {
    const directions: Direction[] = ['TOP', 'LEFT', 'BOTTOM', 'RIGHT']
    const currentIndex = directions.indexOf(currentDirection)
    const nextIndex = clockwise
      ? (currentIndex - 1 + directions.length) % directions.length
      : (currentIndex + 1) % directions.length
    return directions[nextIndex]
  }

  useEffect(() => {
    if (!hovered) {
      const interval = setInterval(() => {
        setDirection((prevState) => rotateDirection(prevState))
      }, duration * 1000)
      return () => clearInterval(interval)
    }
  }, [hovered])
  return (
    <Element
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      className={cn(
        'relative flex h-min w-fit flex-col flex-nowrap content-center items-center justify-center gap-10 overflow-visible rounded-full border bg-black/40 box-decoration-clone p-px backdrop-blur-sm transition duration-500 hover:bg-black/60 dark:bg-white/20',
        containerClassName
      )}
      {...props}
    >
      <div
        className={cn(
          'z-10 w-auto rounded-[inherit] bg-black px-4 py-2 text-white',
          className
        )}
      >
        {children}
      </div>
      <motion.div
        className={cn(
          'absolute inset-0 z-0 flex-none overflow-hidden rounded-[inherit]'
        )}
        style={{
          filter: 'blur(2px)',
          position: 'absolute',
          width: '100%',
          height: '100%',
        }}
        initial={{ background: movingMap[direction] }}
        animate={{
          background: hovered
            ? [movingMap[direction], highlight]
            : movingMap[direction],
        }}
        transition={{ ease: 'linear', duration: duration ?? 1 }}
      />
      <div className='absolute inset-0.5 z-1 flex-none rounded-[100px] bg-black' />
    </Element>
  )
}

export default function HoverBorderDemo() {
  return (
    <HoverBorderGradient>
      <span>Emerald UI Components</span>
    </HoverBorderGradient>
  )
}

```

